// src/analytics.js
// Every event this app can send lives here.
// Naming rule: snake_case, past tense, object first. Properties are short enums.

const track = (name, properties) => {
  if (typeof window !== 'undefined' && window.op) {
    window.op('track', name, properties);
  }
};

export const analytics = {
  signupCompleted: (method) => track('signup_completed', { method }), // 'email' | 'google'
  projectCreated: (source) => track('project_created', { source }), // 'onboarding' | 'dashboard'
  generationRequested: (model) => track('generation_requested', { model }),
  generationFailed: (reason) => track('generation_failed', { reason }), // 'timeout' | 'quota' | 'invalid_input'
  exportDownloaded: (format) => track('export_downloaded', { format }), // 'csv' | 'pdf'
  planUpgraded: (plan) => track('plan_upgraded', { plan }),
};

// src/components/SignupForm.jsx
import { analytics } from '../analytics';

const onSuccess = () => {
  analytics.signupCompleted('google');
};

// Wrong. Personal data in analytics properties, usually by accident.
window.op('track', 'signup_completed', {
  email: user.email,        // no
  name: user.fullName,      // no
  prompt: input.value,      // no, free text is full of personal data
});

// Right. Describe the event, not the person.
window.op('track', 'signup_completed', {
  method: 'google',
  plan: 'free',
  prompt_length: input.value.length,
});

// App-wide context belongs in global properties, set once after init.
window.op('setGlobalProperties', {
  app_version: '2026.07.19',
  environment: 'production',
});
